CREATE TABLE users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, login TEXT UNIQUE NOT NULL, hash TEXT NOT NULL, role TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users, expires INTEGER NOT NULL);
CREATE TABLE customers(id TEXT PRIMARY KEY, data TEXT NOT NULL, version INTEGER NOT NULL);
CREATE TABLE services(id TEXT PRIMARY KEY, data TEXT NOT NULL, version INTEGER NOT NULL);
CREATE TABLE settings(id INTEGER PRIMARY KEY, data TEXT NOT NULL, version INTEGER NOT NULL);
CREATE TABLE documents(seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT UNIQUE NOT NULL, data TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL, updated TEXT NOT NULL);
CREATE TABLE events(id INTEGER PRIMARY KEY, time TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL);
CREATE INDEX events_target ON events(target,id);
CREATE TABLE receipts(user_id INTEGER PRIMARY KEY REFERENCES users, last_event INTEGER NOT NULL);
